_expected_locales = {code for code, _ in LANGUAGE_OPTIONS if code != "en"}
if set(INBOX_FEED_ROWS) != _expected_locales:
    raise ValueError("Inbox feed catalog locale coverage is incomplete")
INBOX_FEED_CATALOGS: dict[str, dict[str, str]] = {
    language: dict(zip(INBOX_FEED_KEYS, row.split("|"), strict=True))
    for language, row in INBOX_FEED_ROWS.items()
}
_formatter = Formatter()
for _language, _entries in INBOX_FEED_CATALOGS.items():
    for _source, _value in _entries.items():
        if not _value.strip() or (_value == _source and len(_source) > 24):
            raise ValueError(
                f"Missing inbox feed translation: {_language}: {_source}"
            )
        if Counter(
            slot for _, slot, _, _ in _formatter.parse(_source) if slot
        ) != Counter(
            slot for _, slot, _, _ in _formatter.parse(_value) if slot
        ):
            raise ValueError(
                f"Inbox feed slot mismatch: {_language}: {_source}"
            )
